Properties.Property:
Процедура ПередЗаписью()
    НачатьТранзакцию();
    Попытка
        Записать(РежимЗаписиДокумента.Проведение);
        // Изменено: добавлена проверка прав
        Если НЕ ПроверкаЗаполнения(Ответственный) Тогда
            ВызватьИсключение("Не указан ответственный!");
        КонецЕсли;
    Исключение
        ОтменитьТранзакцию();
        ВызватьИсключение;
    КонецПопытки;
    ЗафиксироватьТранзакцию();
КонецПроцедуры
